func:
// Thin authenticated proxy to Frigate's snapshot API.
// The companion runs on a phone hotspot and cannot reach Frigate on the LAN,
// so this endpoint gives it a route through the existing remote HTTPS server.
//
// height and quality are pass-through so the panel can tune frame size without
// touching Node-RED. Both are clamped: this endpoint reaches an internal service,
// so it must not forward arbitrary values.

const CAMERA = "avant";
const BASE = "http://192.168.1.133:5000";

function clampInt(v, lo, hi, dflt) {
    const n = parseInt(v, 10);
    if (isNaN(n)) return dflt;
    return Math.min(hi, Math.max(lo, n));
}

const q = msg.req.query || {};
const height = clampInt(q.height, 120, 480, 360);
const quality = clampInt(q.quality, 10, 80, 40);

// Frigate's resize parameter is `height`, not `h` - `h` is silently ignored.
msg.url = BASE + "/api/" + CAMERA + "/latest.jpg"
        + "?height=" + height + "&quality=" + quality;

msg.frigateHeight = height;
msg.frigateQuality = quality;
return msg;

// Return the JPEG straight through. no-store matters: this is a live frame and
// must never be served from a cache.
if (!Buffer.isBuffer(msg.payload) || msg.payload.length < 100) {
    msg.statusCode = 502;
    msg.headers = { "Content-Type": "text/plain" };
    msg.payload = "Frigate returned no image";
    return msg;
}

msg.statusCode = 200;
msg.headers = {
    "Content-Type": "image/jpeg",
    "Content-Length": msg.payload.length,
    "Cache-Control": "no-store",
    "X-Frigate-Height": String(msg.frigateHeight),
    "X-Frigate-Quality": String(msg.frigateQuality)
};
return msg;
